"use strict";
const $=q=>document.querySelector(q), money=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n/100), euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n), number=n=>new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(n), today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Rome'});
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(s,n)=>s?.elements?.namedItem(n)?.value??'';
let state=null,tab=(()=>{const t=new URLSearchParams(location.search).get('tab');return ['panoramica','fatture','inquilini','contabilita','conguagli','chiusure','rendiconti','ripartizioni','scadenze','statistiche'].includes(t)?t:'panoramica'})(),year=new Date().getFullYear(),noticeTimeout;
function alertUI(msg,error=false){const e=$('#message');e.textContent=msg;e.hidden=false;e.className='message'+(error?' error':'');clearTimeout(noticeTimeout);noticeTimeout=setTimeout(()=>e.hidden=true,8500);window.scrollTo({top:0,behavior:'smooth'})}
async function request(path,options={}){let res=await fetch(path,{cache:'no-store',...options});if(!res.ok){let msg=`Errore ${res.status}`;try{msg=(await res.json()).error||msg}catch{}throw Error(msg)}if(res.headers.get('content-type')?.includes('json'))return res.json();return res.blob()}
async function send(path,body){return request(path,{method:'POST',headers:{'Content-Type':'application/json','X-Casa-Consumi':'1'},body:JSON.stringify(body)})}
async function reload(silent=false){try{state=await request('/api/advanced');const reportData=await request('/api/reports');state.reports=reportData.reports;state.reports_bills=reportData.issued_bills;state.payment_preferences=reportData.payment_preferences||[];state.allocation_sources=reportData.allocation_sources||[];state.allocations=reportData.allocations||[];state.generic_sources=reportData.generic_sources||[];state.report_corrections=reportData.report_corrections||[];render();if(!silent)alertUI('Archivio aggiornato')}catch(e){alertUI(e.message,true)}}
function extract(f,n){return f.elements.namedItem(n).value}
function newId(f,n){const v=extract(f,n);return v||''}
function billLabel(b){return ({electricity:'Energia elettrica',gas:'Gas',water:'Acqua'}[b.utility]||b.utility)+' · '+b.start+' → '+b.end+(b.invoiceNumber?' · Fattura n. '+b.invoiceNumber:'')+(b.invoiceDate?' · Emessa il '+niceDate(b.invoiceDate):'')}
function bills(){return state.archive.bills||[]}
function tenants(){return state.archive.tenants||[]}
function optionBills(selected='',empty='Seleziona bolletta'){return `<option value="">${safe(empty)}</option>`+bills().map(b=>`<option value="${safe(b.id)}" ${b.id===selected?'selected':''}>${safe(billLabel(b))}</option>`).join('')}
function optionApts(selected=0){return state.archive.names.map((n,i)=>`<option value="${i}" ${i===selected?'selected':''}>${safe(n)}</option>`).join('')}
function optionTenants(a=0,selected=''){return `<option value="">Non associato / saldo appartamento</option>`+tenants().filter(t=>t.apartment===Number(a)).map(t=>`<option value="${safe(t.id)}" ${t.id===selected?'selected':''}>${safe(t.name)}${t.active?'':' · storico'}</option>`).join('')}
function niceDate(v){if(!v)return '—';const [y,m,d]=v.split('-');return `${d}/${m}/${y}`}
function calc(b){let total=Math.round(Number(b.total)*100),fixed=Math.round(Number(b.fixed)*100),cons=Number(b.generalEnd)-Number(b.generalStart),sub=Number(b.subEnd)-Number(b.subStart),two=b.meterMode==='two_subs',sub2=two?Number(b.sub2End)-Number(b.sub2Start):Math.max(0,cons-sub);if(!Number.isFinite(cons)||!Number.isFinite(sub)||!Number.isFinite(sub2)||cons<0||sub<0||sub2<0||(!two&&sub>cons)||!Number.isFinite(total)||!Number.isFinite(fixed)||fixed<0||total<fixed)throw Error('Letture o importi bolletta non coerenti');let ratio=two?(sub+sub2>0?sub/(sub+sub2):0):(cons>0?sub/cons:0),fs=b.fixedShare1??50,vs=b.variableShare1??(ratio*100);if(!Number.isFinite(Number(fs))||!Number.isFinite(Number(vs))||fs<0||fs>100||vs<0||vs>100)throw Error('Percentuali di ripartizione non valide');let f1=Math.round(fixed*fs/100),v1=Math.round((total-fixed)*vs/100);return {q1:f1+v1,q2:total-f1-v1,f1,v1,f2:fixed-f1,v2:(total-fixed)-v1,c1:sub,c2:sub2,cons,ratio}}
function dueStatus(d){return !d?'Senza scadenza':d<today()?'Scaduto':d===today()?'Scade oggi':'Da scadere'}
function accountingGroups(){
  const m=new Map(),get=(a,tid)=>{let k=a+'|'+(tid||'');if(!m.has(k))m.set(k,{apartment:a,tenantId:tid||'',due:0,received:0,adjustments:0,extra:0,overdue:0,balance:0,credit:0,debit:0});return m.get(k)};
  for(let b of bills()){let c=calc(b);for(let a=0;a<2;a++){let g=get(a,b['tenant'+(a+1)+'Id']||'');let q=c[a?'q2':'q1'];g.due+=q;let v=b['received'+(a+1)],r=v==null?(b['paid'+(a+1)]?q:0):Math.round(Number(v)*100);g.received+=r;let due=b['due'+(a+1)];if(due&&due<today()&&r<q)g.overdue+=q-r;}}
  for(let adj of state.adjustments){let g=get(adj.apartment,adj.tenant_id);g.adjustments+=adj.signed_cents;if(adj.signed_cents>0&&adj.due&&adj.due<today())g.overdue+=adj.signed_cents;}
  for(let rec of state.receipts)get(rec.apartment,rec.tenant_id).extra+=rec.received_cents;
  for(let g of m.values()){g.balance=g.due+g.adjustments-g.received-g.extra;g.credit=Math.max(0,-g.balance);g.debit=Math.max(0,g.balance);g.overdue=Math.max(0,Math.min(g.overdue,g.balance));}
  return [...m.values()];
}
function summary(){let totals=[0,1].map(()=>({due:0,received:0,adjustments:0,extra:0,overdue:0,balance:0,credit:0,debit:0}));for(let g of accountingGroups()){let t=totals[g.apartment];for(let k of ['due','received','adjustments','extra','overdue','credit','debit'])t[k]+=g[k]}for(let t of totals)t.balance=t.debit-t.credit;return totals}

function closed(b){return state.closures.some(c=>c.bill_id===b.id)}
function section(title,body,subtitle=''){return `<section class="card"><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}${body}</section>`}
function empty(txt){return `<div class="empty">${safe(txt)}</div>`}
function panorama(){let s=summary(), totalPDF=state.invoices.length, totalClosed=state.closures.length, overdue=s.reduce((v,x)=>v+x.overdue,0), balance=s.reduce((v,x)=>v+x.balance,0);return `<div class="cards"><div class="card"><div class="label">Bollette registrate</div><strong>${bills().length}</strong><small>${totalClosed} chiuse</small></div><div class="card"><div class="label">Documenti PDF</div><strong>${totalPDF}</strong><small>Memorizzati in SQLite</small></div><div class="card"><div class="label">Saldo complessivo</div><strong class="${balance<0?'positive':''}">${money(balance)}</strong><small>Positivo da ricevere · negativo a credito</small></div><div class="card"><div class="label">Scaduto netto</div><strong class="${overdue?'negative':''}">${money(overdue)}</strong><small>Considerati i crediti e gli incassi</small></div></div>`+section('Situazione dei due appartamenti',`<div class="two-sum">${s.map((t,i)=>`<div class="sum"><span class="label">${safe(state.archive.names[i])}</span><strong class="${t.balance>0?'negative':'positive'}">${money(t.balance)}</strong><p>Bollette: ${money(t.due)} · Conguagli e rettifiche: ${money(t.adjustments)}</p><p>Pagamenti bollette: ${money(t.received)} · Altri incassi: ${money(t.extra)}</p><p>Scaduto netto: <b>${money(t.overdue)}</b></p></div>`).join('')}</div>`,'Saldo positivo = da incassare, saldo negativo = credito da riconoscere o compensare.')+section('Operazioni rapide',`<div class="actions"><button class="btn" data-jump="conguagli">+ Nuovo conguaglio</button><button class="btn light" data-jump="fatture">Allega fattura PDF</button><button class="btn light" data-jump="chiusure">Chiudi un rendiconto</button><button class="btn light" data-jump="rendiconti">Emetti rendiconto cumulativo</button><a class="btn light" href="/">Nuova bolletta</a></div><p class="notice">Il conguaglio non cambia retroattivamente la bolletta: viene registrato come movimento separato e compensato nel saldo. I pagamenti già registrati nelle bollette non vanno registrati di nuovo qui.</p>`);
}
function fatture(){let rows=state.invoices.map(x=>{let b=bills().find(z=>z.id===x.bill_id);return `<tr><td>${safe(x.filename)}<small>${niceDate(x.added_at.slice(0,10))} · ${number(x.size/1024)} KB</small></td><td>${safe(b?billLabel(b):'Bolletta rimossa')}</td><td><a class="small-btn" href="/api/invoices/${encodeURIComponent(x.id)}">Scarica PDF</a> <button class="small-btn danger" data-delete-invoice="${safe(x.id)}">Elimina</button></td></tr>`}).join('');return section('Archivio fatture originali',`<form id="invoiceForm"><div class="fields"><label>Bolletta a cui associare il documento<select name="bill_id" required>${optionBills()}</select></label><label>Fattura originale PDF (massimo 15 MB)<input type="file" name="pdf" accept="application/pdf,.pdf" required></label></div><div class="actions"><button class="btn">Salva fattura sul Raspberry</button></div></form><p class="notice">Il documento PDF viene conservato nel database SQLite: è incluso sia nei backup Home Assistant dell'app, sia nel backup ZIP completo. Il semplice export JSON non conserva i PDF.</p>`)+section('Documenti presenti',rows?`<div class="table-scroll"><table><thead><tr><th>File</th><th>Bolletta collegata</th><th>Azioni</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('Nessuna fattura archiviata.'))}
function inquilini(){let tt=tenants().slice().sort((a,b)=>a.apartment-b.apartment || (b.start||'').localeCompare(a.start||''));return section('Storico conduttori',`<p class="notice">Ogni inquilino mantiene il proprio periodo di locazione. Le bollette sono collegate all’ID anagrafico e la nuova versione conserva anche una fotografia del nominativo utilizzato quando il rendiconto è stato creato. Per inserire un nuovo conduttore usa l’anagrafica principale.</p><div class="actions"><a class="btn light" href="/">Apri anagrafica nella schermata principale</a></div><div class="table-scroll"><table><thead><tr><th>Appartamento</th><th>Conduttore</th><th>Periodo del rapporto</th><th>Stato</th><th>Operazioni</th></tr></thead><tbody>${tt.map(t=>`<tr><td>${safe(state.archive.names[t.apartment])}</td><td><b>${safe(t.name)}</b><small>${safe(t.email||'')}${t.address?'<br>'+safe(t.address):''}</small></td><td>${niceDate(t.start)} → ${niceDate(t.end)}</td><td>${t.active?'<span class="pill">Attivo</span>':'<span class="pill yellow">Archiviato</span>'}</td><td>${t.active?`<button class="small-btn" data-end-tenant="${safe(t.id)}">Termina rapporto</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>${tt.length?'':empty('Nessun conduttore presente.')}`)}
function ledgerRows(a){let rows=[];for(let b of bills()){let c=calc(b),q=c[a?'q2':'q1'];let paid=b['received'+(a+1)];paid=paid==null?(b['paid'+(a+1)]?q:0):Math.round(Number(paid)*100);rows.push({date:b.end,what:'Bolletta · '+billLabel(b),tenant:b['tenant'+(a+1)+'Snapshot']?.name||tenants().find(t=>t.id===b['tenant'+(a+1)+'Id'])?.name||'—',due:q,paid,extra:'',status:closed(b)?'Chiuso':'Aperto'})}for(let adj of state.adjustments.filter(x=>x.apartment===a))rows.push({date:adj.date,what:(adj.kind==='conguaglio'?'Conguaglio':adj.kind==='credito'?'Credito':'Rettifica')+' · '+adj.note,tenant:tenants().find(t=>t.id===adj.tenant_id)?.name||'—',due:adj.signed_cents,paid:0,extra:'',status:dueStatus(adj.due)});for(let r of state.receipts.filter(x=>x.apartment===a))rows.push({date:r.date,what:(r.received_cents<0?'Rimborso · ':'Incasso aggiuntivo · ')+r.note,tenant:tenants().find(t=>t.id===r.tenant_id)?.name||'—',due:0,paid:r.received_cents,extra:'',status:'Incassato'});rows.sort((x,y)=>x.date.localeCompare(y.date));let running=0;return rows.map(r=>{running+=r.due-r.paid;return `<tr><td>${niceDate(r.date)}</td><td>${safe(r.what)}<small>${safe(r.tenant)}</small></td><td class="right">${r.due?money(r.due):'—'}</td><td class="right">${r.paid?money(r.paid):'—'}</td><td class="right"><b class="${running<0?'positive':''}">${money(running)}</b></td></tr>`}).join('')}
function contabilita(){let sm=summary();return section('Contabilità per appartamento',`<div class="two-sum">${sm.map((x,i)=>`<div class="sum"><span class="label">${safe(state.archive.names[i])}</span><strong>${money(x.balance)}</strong><p>Debiti fatturati: ${money(x.due)}</p><p>Conguagli netti: ${money(x.adjustments)}</p><p>Incassati dalle bollette: ${money(x.received)}</p><p>Altri incassi: ${money(x.extra)}</p><p>Crediti distinti da riconoscere: <b>${money(x.credit)}</b></p></div>`).join('')}</div><p class="notice">Saldo progressivo = quote bollette + conguagli/debiti − crediti − pagamenti registrati sulle bollette − incassi aggiuntivi. Il saldo esprime la differenza tra debiti e crediti, ma i crediti di conduttori diversi restano separati: vedi la tabella per conduttore.</p>`)+section('Saldi distinti per conduttore',`<p class="subtle">I crediti di un vecchio conduttore non vengono compensati automaticamente con debiti di quello successivo. Le somme prive di conduttore restano nella voce "Non associato".</p><div class="table-scroll"><table><thead><tr><th>Appartamento</th><th>Conduttore</th><th>Da incassare</th><th>Credito</th><th>Scaduto netto</th></tr></thead><tbody>${accountingGroups().map(g=>`<tr><td>${safe(state.archive.names[g.apartment])}</td><td>${safe(tenants().find(t=>t.id===g.tenantId)?.name||'Non associato')}</td><td>${money(g.debit)}</td><td>${money(g.credit)}</td><td>${money(g.overdue)}</td></tr>`).join('')}</tbody></table></div>`)+sm.map((s,i)=>section('Movimenti · '+safe(state.archive.names[i]),`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Descrizione</th><th class="right">Addebito / credito</th><th class="right">Incasso</th><th class="right">Saldo progressivo</th></tr></thead><tbody>${ledgerRows(i)}</tbody></table></div>`)).join('')+section('Registra incasso aggiuntivo / acconto',`<form id="receiptForm"><div class="fields three"><label>Appartamento<select name="apartment" id="receiptApt">${optionApts()}</select></label><label>Conduttore<select name="tenant_id" id="receiptTenant">${optionTenants()}</select></label><label>Operazione<select name="kind"><option value="incasso">Incasso / acconto</option><option value="rimborso">Rimborso credito al conduttore</option></select></label><label>Importo (€)<input required name="amount" type="number" min="0.01" step="0.01" placeholder="0,00"></label><label>Data incasso<input type="date" name="date" required value="${today()}"></label><label style="grid-column:span 2">Causale<input name="note" maxlength="1000" required placeholder="Es. acconto generico o pagamento conguaglio"></label></div><button class="btn">Registra incasso</button></form><p class="subtle">Registra qui soltanto pagamenti non già annotati nelle schede delle bollette. Un rimborso richiede un credito disponibile del medesimo conduttore; in mancanza viene rifiutato.</p>`)+section('Elimina movimento inserito per errore',`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Appartamento</th><th>Tipo</th><th>Valore</th><th>Causale</th><th></th></tr></thead><tbody>${[...state.receipts.map(x=>({...x,type:'receipts',value:x.received_cents,kind:'Incasso'})),...state.adjustments.map(x=>({...x,type:'adjustments',value:x.signed_cents}))].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${niceDate(x.date)}</td><td>${safe(state.archive.names[x.apartment])}</td><td>${safe(x.kind||'')}</td><td>${money(x.value)}</td><td>${safe(x.note)}</td><td><button class="small-btn danger" data-remove="${safe(x.type)}:${safe(x.id)}">Elimina</button></td></tr>`).join('')}</tbody></table></div>`)}
function conguagli(){return section('Nuovo conguaglio',`<p>Inserisci la somma originariamente addebitata e l'importo definitivo spettante all'appartamento. L'app calcola la differenza e registra un movimento positivo (da incassare) o negativo (credito) senza modificare le vecchie bollette.</p><form id="adjustForm"><div class="fields three"><label>Appartamento<select id="adjApt" name="apartment">${optionApts()}</select></label><label>Conduttore interessato<select id="adjTenant" name="tenant_id">${optionTenants()}</select></label><label>Bolletta di riferimento (facoltativa)<select name="bill_id">${optionBills('','Nessuna / conguaglio autonomo')}</select></label><label>Importo già addebitato (€)<input id="previous" type="number" min="0" step="0.01" required name="previous" placeholder="0,00"></label><label>Importo definitivo (€)<input id="definitive" type="number" min="0" step="0.01" required name="definitive" placeholder="0,00"></label><div class="sum"><span class="label">Differenza da registrare</span><strong id="difference">—</strong><small>Definitivo − già addebitato</small></div><label>Data conguaglio<input required type="date" name="date" value="${today()}"></label><label>Scadenza (facoltativa)<input type="date" name="due"></label><label>Motivazione<input required name="note" maxlength="1000" placeholder="Es. conguaglio annuale energia"></label></div><div class="actions"><button class="btn">Registra conguaglio</button></div></form><p class="notice">Per gli importi a credito la compensazione sul saldo è automatica: un saldo totale negativo rappresenta un credito. Per registrare un rimborso realmente effettuato usa il movimento 'Rimborso credito al conduttore' nella Contabilità: questo riduce il credito disponibile senza creare un nuovo addebito.</p>`)+section('Conguagli e rettifiche già registrati',state.adjustments.length?`<div class="actions"><button type="button" class="btn light" id="printPage">Stampa / salva PDF</button></div><div class="table-scroll"><table><thead><tr><th>Data</th><th>Appartamento / conduttore</th><th>Descrizione</th><th>Già addebitato → definitivo</th><th>Conguaglio</th><th>Scadenza</th></tr></thead><tbody>${state.adjustments.map(x=>`<tr><td>${niceDate(x.date)}</td><td>${safe(state.archive.names[x.apartment])}<small>${safe(tenants().find(t=>t.id===x.tenant_id)?.name||'')}</small></td><td>${safe(x.note)}</td><td>${x.original_cents==null?'—':money(x.original_cents)+' → '+money(x.final_cents)}</td><td class="${x.signed_cents<0?'positive':'negative'}"><b>${money(x.signed_cents)}</b></td><td>${niceDate(x.due)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nessun conguaglio registrato.'))}
function chiusure(){return section('Chiusura rendiconti',`<p>La chiusura salva una fotografia immutabile dei dati della bolletta e impedisce aggiornamenti, modifiche alla ripartizione o eliminazioni fino alla riapertura. Lo sblocco richiede una motivazione e resta nel registro eventi.</p><div class="table-scroll"><table><thead><tr><th>Bolletta e periodo</th><th>Importi ripartiti</th><th>Stato</th><th>Operazione</th></tr></thead><tbody>${bills().map(b=>{let c=calc(b);return `<tr><td><b>${safe(billLabel(b))}</b></td><td>${money(c.q1)} / ${money(c.q2)}</td><td>${closed(b)?'<span class="pill">Chiuso</span>':'<span class="pill yellow">Modificabile</span>'}</td><td><button class="small-btn ${closed(b)?'danger':''}" data-closure="${safe(b.id)}:${closed(b)?'reopen':'close'}">${closed(b)?'Riapri con motivazione':'Chiudi rendiconto'}</button></td></tr>`}).join('')}</tbody></table></div>`)+section('Registro operazioni gestionali',state.events.length?`<div class="table-scroll"><table><thead><tr><th>Quando</th><th>Operazione</th><th>Dettagli</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${safe(e.at.replace('T',' ').slice(0,19))} UTC</td><td>${safe(e.action)}</td><td>${safe(e.context)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nessun evento registrato.'))}
function ripartizioni(){return section('Criteri personalizzati per bolletta',`<p>Per impostazione iniziale il 50% delle spese fisse va a ciascun appartamento, mentre la quota variabile segue le letture del sottocontatore. Qui puoi scegliere percentuali differenti per ogni bolletta. La modifica aggiorna anche i calcoli della schermata principale e i rendiconti, senza alterare il totale generale.</p><form id="splitForm"><label>Seleziona bolletta<select name="bill_id" id="splitBill" required>${optionBills()}</select></label><div class="fields"><label>Percentuale delle spese fisse all'appartamento 1 (%)<input name="fixedShare1" id="fixedShare1" type="number" step="0.01" min="0" max="100" value="50" required></label><label>Percentuale delle spese variabili all'appartamento 1 (%)<input name="variableShare1" id="variableShare1" type="number" step="0.01" min="0" max="100" placeholder="Vuoto = sottocontatore"></label></div><div id="splitPreview" class="sum">Seleziona una bolletta per vedere il dettaglio.</div><div class="actions"><button class="btn">Salva criterio</button></div></form><p class="notice">L'appartamento 1 corrisponde al sottocontatore; l'appartamento 2 al consumo residuo del contatore generale. Le percentuali personalizzate cambiano l'importo attribuito, non i consumi rilevati.</p>`)+section('Criteri attualmente applicati',`<div class="table-scroll"><table><thead><tr><th>Bolletta</th><th>Fissa apt 1</th><th>Variabile apt 1</th><th>Quota 1</th><th>Quota 2</th><th>Stato</th></tr></thead><tbody>${bills().map(b=>{let c=calc(b);return `<tr><td>${safe(billLabel(b))}</td><td>${number(b.fixedShare1??50)}%</td><td>${b.variableShare1==null?'Secondo contatore':number(b.variableShare1)+'%'}</td><td>${money(c.q1)}</td><td>${money(c.q2)}</td><td>${closed(b)?'Chiuso':'Aperto'}</td></tr>`}).join('')}</tbody></table></div>`)}
function scadenze(){let entries=[];for(const b of bills()){let c=calc(b);for(let i=0;i<2;i++){let amount=c[i?'q2':'q1'],v=b['received'+(i+1)],received=v==null?(b['paid'+(i+1)]?amount:0):Math.round(Number(v)*100),due=b['due'+(i+1)]||'';if(amount>received)entries.push({date:due,apartment:i,what:'Bolletta '+billLabel(b),amount:amount-received})}}for(let x of state.adjustments){if(x.signed_cents>0)entries.push({date:x.due,apartment:x.apartment,what:'Conguaglio: '+x.note,amount:x.signed_cents})}entries.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));let sm=summary();return section('Scadenzario e insoluti',`<div class="two-sum">${sm.map((s,i)=>`<div class="sum"><span class="label">${safe(state.archive.names[i])}</span><strong class="${s.overdue?'negative':''}">${money(s.overdue)}</strong><p>Totale scaduto netto, dopo i crediti e gli altri incassi</p></div>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>Scadenza</th><th>Appartamento</th><th>Documento</th><th>Importo residuo</th><th>Stato</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${niceDate(e.date)}</td><td>${safe(state.archive.names[e.apartment])}</td><td>${safe(e.what)}</td><td><b>${money(e.amount)}</b></td><td><span class="pill ${e.date&&e.date<today()?'red':'yellow'}">${dueStatus(e.date)}</span></td></tr>`).join('')}</tbody></table></div><p class="notice">La tabella mostra i singoli importi ancora aperti. Lo scaduto netto considera solo crediti e incassi aggiuntivi dello stesso conduttore, senza imputarli automaticamente a una bolletta specifica.</p>`)+section('Notifiche tramite Home Assistant',`<p>Puoi attivare il controllo giornaliero delle scadenze nella configurazione dell'app Home Assistant e indicare il servizio <code>notify</code> del telefono. L'app invierà un riepilogo degli insoluti netti una volta al giorno, soltanto se presente un saldo scaduto.</p><div class="actions"><button class="btn light" id="notifyTest">Invia notifica di prova</button></div><p class="subtle">Nella configurazione Home Assistant dell'add-on: <code>notifications_enabled: true</code>, <code>notify_service: notify.mobile_app_nome_dispositivo</code>, <code>notify_hour: "09:00"</code>. Riavvia dopo aver modificato la configurazione. Se il servizio è disattivato o inesistente non partiranno avvisi.</p>`)}
function statistiche(){let yy=new Set(bills().map(b=>Number(b.end.slice(0,4))));yy.add(year);let filtered=bills().filter(b=>b.end.startsWith(String(year)));let annual={electricity:[[0,0],[0,0]],gas:[[0,0],[0,0]],water:[[0,0],[0,0]]};let months=Array.from({length:12},(_,i)=>({label:String(i+1).padStart(2,'0'),parts:[0,0]}));for(let b of filtered){let c=calc(b),a=annual[b.utility];if(!a)continue;a[0][0]+=c.q1;a[0][1]+=c.q2;a[1][0]+=c.c1;a[1][1]+=c.c2;let m=Number(b.end.slice(5,7))-1;months[m].parts[0]+=c.q1;months[m].parts[1]+=c.q2;}const biggest=Math.max(1,...months.map(m=>m.parts[0]+m.parts[1]));return section('Statistiche annuali',`<div class="fields"><label>Anno di competenza (anno di fine periodo)<select id="yearSelect">${[...yy].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${year===y?'selected':''}>${y}</option>`).join('')}</select></label><div class="sum"><span class="label">Bollette nell'anno</span><strong>${filtered.length}</strong><small>Attribuite in base alla fine del periodo di fornitura</small></div></div><div class="legend"><span><i class="dot"></i>${safe(state.archive.names[0])}</span><span><i class="dot other"></i>${safe(state.archive.names[1])}</span></div><h3>Spesa attribuita per mese</h3><div class="stats-bars">${months.map(m=>`<div class="bar-line"><span>${m.label}/${year}</span><div class="track"><div class="part0" title="${safe(state.archive.names[0])}: ${money(m.parts[0])}" style="width:${100*m.parts[0]/biggest}%"></div><div class="part1" title="${safe(state.archive.names[1])}: ${money(m.parts[1])}" style="width:${100*m.parts[1]/biggest}%"></div></div><b>${money(m.parts[0]+m.parts[1])}</b></div>`).join('')}</div>`)+section('Totali per utenza e per appartamento',`<div class="table-scroll"><table><thead><tr><th>Utenza</th><th>${safe(state.archive.names[0])} · €</th><th>${safe(state.archive.names[1])} · €</th><th>Consumo 1</th><th>Consumo 2</th></tr></thead><tbody>${Object.entries(annual).map(([u,v])=>`<tr><td>${safe(({electricity:'Elettricità',gas:'Gas',water:'Acqua'})[u])}</td><td>${money(v[0][0])}</td><td>${money(v[0][1])}</td><td>${number(v[1][0])} ${u==='electricity'?'kWh':'m³'}</td><td>${number(v[1][1])} ${u==='electricity'?'kWh':'m³'}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Le statistiche riguardano le quote delle bollette; i conguagli compaiono nella contabilità e sono contabilizzati alla data della loro registrazione.</p>`)}

// Emissioni cumulative separate dalla contabilizzazione delle singole bollette.
let reportSelection={apartment:0,tenant_id:''};
function plusMonthISO(iso){if(!iso)return '';const d=new Date(iso+'T12:00:00Z');let y=d.getUTCFullYear(),m=d.getUTCMonth()+1,day=d.getUTCDate();if(m===12){y++;m=0;}const last=new Date(Date.UTC(y,m+1,0)).getUTCDate();return `${y}-${String(m+1).padStart(2,'0')}-${String(Math.min(day,last)).padStart(2,'0')}`;}
function issuedIds(apartment){const ids=new Set();for(const report of state.reports||[]){if(report.apartment===apartment && Array.isArray(report.bill_ids))for(const id of report.bill_ids)ids.add(id)}return ids;}
function reportShare(b,a){const share=calc(b);return a===0?share.q1:share.q2;}
function reportRemaining(b,a){const q=reportShare(b,a);const i=a+1,v=b['received'+i];const got=v==null?(b['paid'+i]?q:0):Math.round(Number(v)*100);const allocated=(state.allocations||[]).filter(x=>!x.voided_at&&x.bill_id===b.id&&x.apartment===a).reduce((n,x)=>n+x.amount_cents,0);return Math.max(0,q-(Number.isFinite(got)?got:0)-allocated);}
function reconciliationPanel(apt,tid){
 const sources=(state.allocation_sources||[]).filter(x=>x.apartment===apt&&x.tenant_id===tid);
 const eligible=bills().filter(b=>b['tenant'+(apt+1)+'Id']===tid&&reportRemaining(b,apt)>0);
 const used=new Set((state.reports_bills||[]).filter(x=>x.apartment===apt).map(x=>x.bill_id));
 const allocations=(state.allocations||[]).filter(x=>x.apartment===apt&&x.tenant_id===tid);
 const sourceNames={receipt:'Incasso',credit:'Credito'};
 let html='<p>Associa manualmente un incasso o credito già registrato a una quota. Non si crea un secondo incasso e il saldo contabile non cambia.</p>';
 html+='<form id="reconciliationForm"><div class="fields three"><label>Movimento<select name="source" required><option value="">Seleziona movimento</option>';
 html+=sources.map(x=>'<option value="'+safe(x.kind+':'+x.source_id)+'">'+safe(sourceNames[x.kind])+' · '+niceDate(x.date)+' · disponibile '+money(x.available_cents)+'</option>').join('');
 html+='</select></label><label>Bolletta e quota<select name="bill_id" required><option value="">Seleziona bolletta</option>';
 html+=eligible.map(b=>'<option value="'+safe(b.id)+'">'+safe(billLabel(b))+' · residuo '+money(reportRemaining(b,apt))+(used.has(b.id)?' · rendiconto emesso':'')+'</option>').join('');
 html+='</select></label><label>Importo da attribuire (€)<input type="number" name="amount" required min="0.01" step="0.01"></label></div>';
 html+='<div class="actions"><button type="submit" class="btn" '+(!sources.length||!eligible.length?'disabled':'')+'>Registra attribuzione</button></div></form>';
 html+='<p class="subtle">Nessuna imputazione automatica. Se esistono movimenti senza conduttore associato, occorre prima regolarizzarli. I rendiconti già emessi non vengono modificati.</p>';
 if(allocations.length){
  html+='<h3>Attribuzioni registrate</h3><div class="table-wrap"><table><thead><tr><th>Movimento</th><th>Bolletta</th><th>Importo</th><th>Operazione</th></tr></thead><tbody>';
  html+=allocations.map(x=>'<tr><td>'+safe(sourceNames[x.source_kind]||x.source_kind)+' '+safe(x.source_id.slice(0,8))+'</td><td>'+safe(billLabel(bills().find(b=>b.id===x.bill_id)||{utility:'',start:'',end:''}))+'</td><td>'+money(x.amount_cents)+'</td><td>'+(used.has(x.bill_id)?'Rendiconto emesso · immutabile':'<button type="button" class="small-btn" data-revoke-allocation="'+safe(x.id)+'">Annulla</button>')+'</td></tr>').join('');
  html+='</tbody></table></div>';
 }
 return section('Riconciliazione esplicita dei pagamenti',html);
}

function correctionPanels(apt,tid){
 const sourceNames={receipt:'Incasso',credit:'Credito'};
 const generics=(state.generic_sources||[]).filter(x=>x.apartment===apt);
 const active=(state.allocations||[]).filter(x=>!x.voided_at&&x.apartment===apt&&x.tenant_id===tid);
 const issuedIds=new Set((state.reports_bills||[]).filter(x=>x.apartment===apt).map(x=>x.bill_id));
 const correctable=active.filter(x=>issuedIds.has(x.bill_id));
 const corrections=(state.report_corrections||[]).filter(x=>x.apartment===apt&&x.tenant_id===tid);
 let html='';
 if(generics.length){
  html+='<p>Se il movimento è riferito al solo appartamento, assegnalo integralmente a un conduttore soltanto dopo verifica documentale. Non vengono creati nuovi incassi.</p>';
  html+='<form id="genericAssignForm"><div class="fields three"><label>Movimento senza conduttore<select name="source" required><option value="">Seleziona</option>';
  html+=generics.map(x=>'<option value="'+safe(x.source_kind+':'+x.source_id)+'">'+safe(sourceNames[x.source_kind])+' · '+niceDate(x.date)+' · '+money(x.amount_cents)+'</option>').join('');
  html+='</select></label><label>Conduttore destinatario<input readonly value="'+safe(tenants().find(x=>x.id===tid)?.name||'Seleziona conduttore')+'"></label>';
  html+='<label>Motivazione documentata<input name="reason" type="text" minlength="12" maxlength="500" required placeholder="Indica il riferimento verificato"></label></div>';
  html+='<button type="submit" class="btn" '+(tid?'':'disabled')+'>Associa intero movimento</button></form>';
 }else html+='<p>Nessun incasso o credito privo di conduttore per questo appartamento.</p>';
 html+='<p class="subtle">Per rettificare un’attribuzione di un rendiconto già emesso si registra una nuova nota: il PDF originario rimane immutato.</p>';
 if(correctable.length){
  html+='<div class="table-wrap"><table><thead><tr><th>Attribuzione</th><th>Bolletta</th><th>Importo</th><th>Rettifica</th></tr></thead><tbody>';
  html+=correctable.map(x=>'<tr><td>'+safe(x.id.slice(0,12))+'</td><td>'+safe(billLabel(bills().find(b=>b.id===x.bill_id)||{utility:'',start:'',end:''}))+'</td><td>'+money(x.amount_cents)+'</td><td><button type="button" class="small-btn" data-correct-issued="'+safe(x.id)+'">Registra nota</button></td></tr>').join('');
  html+='</tbody></table></div>';
 }
 if(corrections.length){
  html+='<h3>Note di rettifica emesse</h3><div class="table-wrap"><table><thead><tr><th>Numero</th><th>Rendiconto</th><th>Importo</th><th>Nota PDF</th></tr></thead><tbody>';
  html+=corrections.map(x=>'<tr><td>'+safe(x.serial)+'</td><td>'+safe((state.reports||[]).find(r=>r.id===x.report_id)?.label||x.report_id)+'</td><td>'+money(x.amount_cents)+'</td><td><a class="small-btn" target="_blank" rel="noopener" href="/api/reports/correction/pdf/'+encodeURIComponent(x.id)+'">Scarica nota</a></td></tr>').join('');
  html+='</tbody></table></div>';
 }
 return section('Regolarizzazioni e note di rettifica',html);
}
function rendiconti(){const apt=reportSelection.apartment, availableTenants=tenants().filter(t=>t.apartment===apt);
 if(!availableTenants.some(t=>t.id===reportSelection.tenant_id))reportSelection.tenant_id=availableTenants.find(t=>t.active)?.id||availableTenants[0]?.id||'';
 const tid=reportSelection.tenant_id;
 const paymentProfile=state.payment_preferences?.[apt]||{enabled:false,beneficiary:'',iban:'',reference:'',instructions:''};
 const used=state.reports_bills||[];
 const issued=new Set(used.filter(x=>x.apartment===apt).map(x=>x.bill_id));
 const eligible=bills().filter(b=>b['tenant'+(apt+1)+'Id']===tid && !issued.has(b.id) && reportRemaining(b,apt)>0);
 const unassigned=bills().filter(b=>!b['tenant'+(apt+1)+'Id'] && !closed(b) && !issued.has(b.id) && reportShare(b,apt)>0);
 const rows=(state.reports||[]).map(r=>`<tr><td><b>${safe(r.label)}</b><small>${niceDate(r.issued_on)}</small></td><td>${safe(state.archive.names[r.apartment])}<small>${safe(r.tenant_name)}</small></td><td>${r.bill_count} bollette</td><td>${money(r.amount_cents)}</td><td>${niceDate(r.due_on)}</td><td>${r.reconciliation_required?'Da verificare':money(r.remaining_cents)}<small>${safe(({scaduto:'Scaduto',pagato:'Pagato',parziale:'Parziale',da_ricevere:'Da ricevere',da_riconciliare:'Incassi/crediti da riconciliare',rettificato:'Rettifica emessa · verificare saldo'})[r.status]||r.status)}</small></td><td><a class="small-btn" target="_blank" rel="noopener" href="/api/reports/pdf/${encodeURIComponent(r.id)}">Scarica PDF</a></td></tr>`).join('');
 const association=section('Associa conduttore a bolletta già contabilizzata',
    '<p class="subtle">Se una bolletta è stata contabilizzata prima di creare l’anagrafica, puoi assegnare la sola quota non ancora associata. Non vengono modificati importi, letture, pagamenti o rendiconti emessi.</p>'+
    (unassigned.length && tid?`<form id="assignBillTenantForm"><div class="fields three"><label>Bolletta senza conduttore<select name="bill_id" required><option value="">Seleziona bolletta</option>${unassigned.map(b=>`<option value="${safe(b.id)}">${safe(billLabel(b))} · Quota ${money(reportShare(b,apt))}</option>`).join('')}</select></label><label>Appartamento<input readonly value="${safe(state.archive.names[apt])}"></label><label>Conduttore<input readonly value="${safe(tenants().find(t=>t.id===tid)?.name||'')}"></label></div><button class="btn" type="submit">Associa e salva sulla bolletta</button></form>`:
    '<p class="subtle">Nessuna quota libera associabile all’appartamento selezionato. Le bollette chiuse, già rendicontate o già intestate non sono modificabili da questa funzione.</p>')
  );
 return association+reconciliationPanel(apt,tid)+correctionPanels(apt,tid)+section('Emetti rendiconto cumulativo',`<p>Un solo rendiconto per appartamento e conduttore, con una o più bollette di luce, gas e acqua. Include soltanto le quote effettivamente dovute. La generazione del PDF <b>non crea nuovi crediti</b> e non registra movimenti in Finance.</p>
 <form id="reportForm"><div class="fields three"><label>Appartamento<select id="reportApartment" name="apartment">${optionApts(apt)}</select></label><label>Conduttore<select id="reportTenant" name="tenant_id">${availableTenants.map(t=>`<option value="${safe(t.id)}" ${t.id===tid?'selected':''}>${safe(t.name)}</option>`).join('')}</select></label><div></div><label>Data di emissione<input type="date" id="reportIssued" name="issued_on" value="${today()}" required></label><label>Scadenza pagamento (modificabile)<input type="date" id="reportDue" name="due_on" value="${plusMonthISO(today())}" required></label></div>
 <div class="report-payment-box">
 <label class="report-check"><input type="checkbox" id="reportPaymentEnabled" name="payment_enabled" ${paymentProfile.enabled?'checked':''}><span><b>Includi dati per il pagamento nel PDF</b></span></label>
 <div class="report-payment-fields" id="reportPaymentFields" ${paymentProfile.enabled?'':'hidden'}>
 <div class="fields"><label>Intestatario del conto<input type="text" name="payment_beneficiary" maxlength="150" autocomplete="off" value="${safe(paymentProfile.beneficiary)}" placeholder="Intestatario beneficiario"></label>
 <label>IBAN<input type="text" name="payment_iban" maxlength="50" autocomplete="off" spellcheck="false" value="${safe(paymentProfile.iban)}" placeholder="IT00 A000 0000 0000 0000 0000 000"></label></div>
 <div class="fields"><label>Causale personalizzata (facoltativa)<input type="text" name="payment_reference" maxlength="160" value="${safe(paymentProfile.reference)}" placeholder="Vuoto = Rendiconto ZEUS + numero + appartamento"></label>
 <label>Indicazioni aggiuntive (facoltative)<input type="text" name="payment_instructions" maxlength="250" value="${safe(paymentProfile.instructions)}" placeholder="Ulteriori istruzioni per il pagamento"></label></div>
 </div>
 <div class="actions"><button type="button" id="reportPaymentSave" class="btn light">Salva come dati predefiniti per questo appartamento</button></div>
 <p class="subtle">Puoi modificare i dati per un singolo rendiconto senza salvarli come predefiniti. L'anteprima mostra come compariranno nel PDF. I documenti già emessi conservano i dati originali.</p>
 </div>
 <h3>Bollette da includere (${eligible.length} disponibili)</h3>${eligible.length?`<div class="report-bills">${eligible.map(b=>`<label class="report-check"><input type="checkbox" name="bill_id" value="${safe(b.id)}" checked><span>${safe(billLabel(b))} <b>${money(reportRemaining(b,apt))} da versare</b></span></label>`).join('')}</div>`:empty('Nessuna bolletta non ancora rendicontata per il conduttore selezionato.')}
 <p class="notice">L'anteprima non assegna un numero e non registra nulla. Solo «Emetti» assegna il progressivo annuale e blocca gli importi delle bollette incluse. I pagamenti potranno ancora essere aggiornati.</p>
 <div class="actions"><button class="btn light" type="button" id="reportPreview" ${eligible.length?'':'disabled'}>Anteprima PDF</button><button class="btn" type="submit" ${eligible.length?'':'disabled'}>Emetti e numera rendiconto</button></div></form>`,'La scadenza predefinita è un mese di calendario dopo l’emissione; puoi modificarla prima di confermare.')+
 section('Registro dei rendiconti emessi',rows?`<div class="table-scroll"><table><thead><tr><th>N.</th><th>Destinatario</th><th>Bollette</th><th>Totale</th><th>Scadenza</th><th>Residuo*</th><th>PDF</th></tr></thead><tbody>${rows}</tbody></table></div><p class="subtle">*Residuo calcolato dai pagamenti registrati sulle singole bollette. Se ci sono incassi o crediti non imputati il residuo è sospeso: verificare la situazione contabile prima di richiedere ulteriori pagamenti. Nessuna imputazione automatica; i PDF già emessi restano invariati.</p>`:empty('Non sono ancora stati emessi rendiconti numerati.'));
}
function reportPayment(form){return {enabled:!!form.querySelector('[name="payment_enabled"]')?.checked,beneficiary:val(form,'payment_beneficiary').trim(),iban:val(form,'payment_iban').trim(),reference:val(form,'payment_reference').trim(),instructions:val(form,'payment_instructions').trim()};}
function reportPayload(form){const data={apartment:Number(val(form,'apartment')),tenant_id:val(form,'tenant_id'),issued_on:val(form,'issued_on'),due_on:val(form,'due_on'),bill_ids:[...form.querySelectorAll('input[name="bill_id"]:checked')].map(n=>n.value),payment:reportPayment(form)};
 if(!data.tenant_id)throw Error('Seleziona un conduttore');if(!data.bill_ids.length)throw Error('Seleziona almeno una bolletta');return data;
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function render(){if(!state)return;const pages={panoramica:panorama,fatture,inquilini,contabilita,conguagli,chiusure,rendiconti,ripartizioni,scadenze,statistiche};$('#panel').innerHTML=pages[tab]();document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));bindDynamic()}
const MANAGEMENT_TABS=new Set(['panoramica','fatture','inquilini','contabilita','conguagli','chiusure','rendiconti','ripartizioni','scadenze','statistiche']);
function jump(to){
  if(!MANAGEMENT_TABS.has(to))return;
  const changed=tab!==to;tab=to;render();
  if(changed){
    const url=new URL(location.href);url.searchParams.set('tab',to);
    const next=url.pathname+url.search+url.hash;
    // The parent shell owns browser history: do not add child-frame history entries.
    if(window.parent!==window)history.replaceState(history.state,'',next);
    else history.pushState(history.state,'',next);
    window.dispatchEvent(new Event('zeus-navigation-change'));
  }
  window.scrollTo({top:0,behavior:'smooth'});
}
window.addEventListener('popstate',()=>{
  const requested=new URLSearchParams(location.search).get('tab');
  const next=MANAGEMENT_TABS.has(requested)?requested:'panoramica';
  if(next!==tab){tab=next;render();}
});
function bindDynamic(){if($('#reportApartment'))$('#reportApartment').onchange=e=>{reportSelection.apartment=Number(e.target.value);reportSelection.tenant_id='';render()};if($('#reportTenant'))$('#reportTenant').onchange=e=>{reportSelection.tenant_id=e.target.value;render()};if($('#reportIssued'))$('#reportIssued').onchange=e=>{$('#reportDue').value=plusMonthISO(e.target.value)};if($('#reportPaymentEnabled'))$('#reportPaymentEnabled').onchange=e=>{$('#reportPaymentFields').hidden=!e.target.checked};if($('#receiptApt'))$('#receiptApt').onchange=()=>{$('#receiptTenant').innerHTML=optionTenants($('#receiptApt').value)};if($('#adjApt'))$('#adjApt').onchange=()=>{$('#adjTenant').innerHTML=optionTenants($('#adjApt').value)};if($('#splitBill')){$('#splitBill').onchange=onSplitBill;['fixedShare1','variableShare1'].forEach(id=>$('#'+id).oninput=previewSplit)};if($('#previous'))['previous','definitive'].forEach(id=>$('#'+id).oninput=previewDifference);if($('#yearSelect'))$('#yearSelect').onchange=e=>{year=Number(e.target.value);render()};}
function onSplitBill(){const b=bills().find(b=>b.id===$('#splitBill').value);if(!b)return;$('#fixedShare1').value=b.fixedShare1??50;$('#variableShare1').value=b.variableShare1??'';previewSplit()}
function previewSplit(){const b=bills().find(b=>b.id===$('#splitBill')?.value);if(!b)return;let fixed=Number($('#fixedShare1').value),variable=$('#variableShare1').value===''?null:Number($('#variableShare1').value);if(!Number.isFinite(fixed)||fixed<0||fixed>100||variable!=null&&(variable<0||variable>100)){ $('#splitPreview').textContent='Percentuali non valide';return}let c=calc({...b,fixedShare1:fixed,...variable==null?{variableShare1:null}:{variableShare1:variable}});$('#splitPreview').innerHTML=`<b>${safe(state.archive.names[0])}</b>: ${money(c.q1)} · <b>${safe(state.archive.names[1])}</b>: ${money(c.q2)}<br><small>Totale riconciliato: ${money(c.q1+c.q2)}</small>`}
function previewDifference(){const old=Number($('#previous').value),def=Number($('#definitive').value);$('#difference').textContent=$('#previous').value&&$('#definitive').value?euro(def-old)+' · '+(def-old>0?'da incassare':def-old<0?'credito':'nessuna differenza'):'—'}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>jump(b.dataset.tab));$('#refresh').onclick=()=>reload();
$('#panel').addEventListener('click',async e=>{let node=e.target.closest('[data-jump],[data-end-tenant],[data-delete-invoice],[data-remove],[data-closure],[data-revoke-allocation],[data-correct-issued],#notifyTest,#printPage,#reportPreview,#reportPaymentSave');if(!node)return;try{if(node.id==='reportPaymentSave'){const form=$('#reportForm');await send('/api/reports/payment-settings',{apartment:Number(val(form,'apartment')),payment:reportPayment(form)});state.payment_preferences[reportSelection.apartment]=reportPayment(form);alertUI('Dati di pagamento predefiniti salvati per questo appartamento');return}if(node.id==='reportPreview'){const data=reportPayload($('#reportForm'));const pdf=await request('/api/reports/preview',{method:'POST',headers:{'Content-Type':'application/json','X-Casa-Consumi':'1'},body:JSON.stringify(data)});downloadBlob(pdf,'ZEUS_Anteprima_Rendiconto.pdf');return}if(node.dataset.jump){jump(node.dataset.jump);return}if(node.dataset.endTenant){const end=prompt('Indica la data di fine locazione (AAAA-MM-GG):',today());if(!end)return;if(!confirm('Terminare il rapporto per la data '+end+'?'))return;await send('/api/advanced/tenant_end',{tenant_id:node.dataset.endTenant,end});await reload(true);alertUI('Rapporto archiviato, le bollette storiche restano conservate');return}if(node.dataset.correctIssued){const reason=prompt('Motivazione documentata della rettifica (almeno 12 caratteri):','');if(!reason||!confirm('L’attribuzione verrà annullata nel saldo corrente; il rendiconto originale resterà immutato. Confermi?'))return;await send('/api/reports/correct-issued',{allocation_id:node.dataset.correctIssued,reason});await reload(true);alertUI('Nota registrata. Scarica il PDF nel registro.');return}if(node.dataset.revokeAllocation){const reason=prompt('Motivazione dell’annullamento dell’attribuzione (obbligatoria):','');if(!reason)return;await send('/api/reports/revoke-allocation',{id:node.dataset.revokeAllocation,reason});await reload(true);alertUI('Attribuzione annullata');return}if(node.dataset.deleteInvoice){if(!confirm('Eliminare definitivamente il documento originale?'))return;await send('/api/advanced/invoice/delete',{id:node.dataset.deleteInvoice});await reload(true);alertUI('Documento eliminato');return}if(node.dataset.remove){if(!confirm('Eliminare definitivamente questo movimento? L’operazione viene registrata nello storico.'))return;let [type,id]=node.dataset.remove.split(':');await send('/api/advanced/delete',{type,id});await reload(true);alertUI('Movimento eliminato');return}if(node.dataset.closure){let [bill_id,action]=node.dataset.closure.split(':');let reason='';if(action==='close'){if(!confirm('Chiudere questo rendiconto? Non potrai più modificarne i valori senza riaprirlo.'))return}else{reason=prompt('Motivazione obbligatoria della riapertura:','');if(!reason?.trim())return}await send('/api/advanced/closure',{bill_id,action,reason});await reload(true);alertUI(action==='close'?'Rendiconto chiuso':'Rendiconto riaperto');return}if(node.id==='printPage'){window.print();return}if(node.id==='notifyTest'){await send('/api/advanced/notify/test',{});alertUI('Richiesta di notifica inviata a Home Assistant');return}}catch(err){alertUI(err.message,true)}});
$('#panel').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const btn=form.querySelector('button[type=submit],button:not([type])');if(btn)btn.disabled=true;try{if(form.id==='assignBillTenantForm'){
   const bill_id=val(form,'bill_id'),tenant_id=reportSelection.tenant_id,apartment=reportSelection.apartment;
   if(!bill_id||!tenant_id)throw Error('Seleziona bolletta e conduttore');
   if(!confirm('Associare la quota della bolletta a questo conduttore senza modificare importi o pagamenti?'))return;
   const result=await send('/api/advanced/assign-bill-tenant',{bill_id,tenant_id,apartment});
   await reload(true);alertUI('Conduttore associato alla quota di '+money(result.share_cents)+'. Ora puoi generare il rendiconto.');return;
  }else if(form.id==='reportForm'){if(!confirm('Emettere definitivamente questo rendiconto? Verrà assegnato un numero annuale e le bollette non potranno essere reinserite in un altro rendiconto.'))return;const result=await send('/api/reports/issue',reportPayload(form));await reload(true);alertUI('Rendiconto '+result.label+' emesso. Scadenza '+niceDate(result.due_on));const pdf=await request('/api/reports/pdf/'+encodeURIComponent(result.id));downloadBlob(pdf,'ZEUS_Rendiconto_'+result.label.replace('/','-')+'.pdf');return;}else if(form.id==='invoiceForm'){let f=form.elements.pdf.files[0];if(!f||f.size>15*1024*1024)throw Error('Seleziona un PDF massimo 15 MB');const q=new URLSearchParams({bill_id:val(form,'bill_id'),filename:f.name});await request('/api/invoices?'+q,{method:'POST',headers:{'Content-Type':'application/pdf','X-Casa-Consumi':'1'},body:f});}
else if(form.id==='genericAssignForm'){const [source_kind,source_id]=val(form,'source').split(':');await send('/api/reports/assign-generic',{source_kind,source_id,tenant_id:reportSelection.tenant_id,reason:val(form,'reason')});await reload(true);alertUI('Movimento associato al conduttore senza creare nuovi incassi');return;}
else if(form.id==='reconciliationForm'){const [source_kind,source_id]=val(form,'source').split(':');await send('/api/reports/allocate',{source_kind,source_id,bill_id:val(form,'bill_id'),amount:val(form,'amount')});await reload(true);alertUI('Attribuzione registrata senza creare nuovi incassi');return;}
else if(form.id==='receiptForm'){await send('/api/advanced/receipt',{apartment:Number(val(form,'apartment')),tenant_id:val(form,'tenant_id'),kind:val(form,'kind'),amount:val(form,'amount'),date:val(form,'date'),note:val(form,'note')})}
else if(form.id==='adjustForm'){let previous=Number(val(form,'previous')),definitive=Number(val(form,'definitive'));let diff=Math.round(definitive*100)-Math.round(previous*100);if(!Number.isFinite(diff)||diff===0)throw Error('Il conguaglio è pari a zero');await send('/api/advanced/adjustment',{apartment:Number(val(form,'apartment')),tenant_id:val(form,'tenant_id'),bill_id:val(form,'bill_id'),kind:'conguaglio',previous:val(form,'previous'),definitive:val(form,'definitive'),amount:(diff/100).toFixed(2),date:val(form,'date'),due:val(form,'due'),note:val(form,'note')})}
else if(form.id==='splitForm'){let raw=val(form,'variableShare1');await send('/api/advanced/split',{bill_id:val(form,'bill_id'),fixedShare1:Number(val(form,'fixedShare1')),variableShare1:raw===''?null:Number(raw)})}
else return;
await reload(true);alertUI('Operazione salvata sul Raspberry');
}catch(err){alertUI(err.message,true)}finally{if(btn)btn.disabled=false}});
